(7476091, 1188206, 10785, '<td valign="top">Great execution. Camera angle and perspective are all good. Work on the staging to create a dramatic scene.</td>', 'Great execution. Camera angle and perspective are all good. Work on the staging to create a dramatic scene.', '2016-09-28 08:24:12.000000', NULL, 1),
(7476233, 1188187, 63218, '<td valign="top">the reflection is an extra bonus</td>', 'the reflection is an extra bonus', '2016-09-29 10:26:09.000000', NULL, 1),
(7476234, 1188224, 63218, '<td valign="top">The black lipstick is a little unusual, in fact the whole thing is odd. But charming. I hope you got a shot of the wall, for texture.</td>', 'The black lipstick is a little unusual, in fact the whole thing is odd. But charming. I hope you got a shot of the wall, for texture.', '2016-09-29 10:35:31.000000', NULL, 1),
